#!/usr/bin/env python3
import os
import re
import sys
import signal

try:
    signal.signal(signal.SIGPIPE, signal.SIG_DFL)
except Exception:
    pass

VERSION = "1.0.0"


def prog_name() -> str:
    return os.path.basename(sys.argv[0]) or "executable"


def long_help(prog: str) -> str:
    return f"""sd v1.0.0
An intuitive find & replace CLI

Usage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using `-F`) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like `-f mc`).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make `.` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
"""


def short_help(prog: str) -> str:
    return f"""sd v1.0.0
An intuitive find & replace CLI

Usage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>          The regexp or string (if using `-F`) to search for
  <REPLACE_WITH>  What to replace each match with. Unless in string mode, you may use captured
                  values like $1, $2, etc
  [FILES]...      The path to file(s). This is optional - sd can also read from STDIN

Options:
  -p, --preview                   Display changes in a human reviewable format (the specifics of the
                                  format are likely to change in the future)
  -F, --fixed-strings             Treat FIND and REPLACE_WITH args as literal strings
  -n, --max-replacements <LIMIT>  Limit the number of replacements that can occur per file. 0
                                  indicates unlimited replacements [default: 0]
  -f, --flags <FLAGS>             Regex flags. May be combined (like `-f mc`).
  -h, --help                      Print help (see more with '--help')
  -V, --version                   Print version
"""


class ParseExit(Exception):
    def __init__(self, code: int):
        self.code = code


class Opts:
    def __init__(self):
        self.preview = False
        self.fixed = False
        self.max_replacements = 0
        self.flags = ""
        self.seen_preview = False
        self.seen_fixed = False
        self.seen_max = False
        self.seen_flags = False
        self.positionals = []


def print_parse_error(msg: str, usage: str = None):
    prog = prog_name()
    if usage is None:
        usage = f"Usage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]..."
    sys.stderr.write(f"error: {msg}\n\n{usage}\n\nFor more information, try '--help'.\n")


def active_usage(opts: Opts) -> str:
    prog = prog_name()
    # Clap's missing-argument usage specializes to the options that were supplied.
    parts = []
    if opts.seen_preview:
        parts.append("--preview")
    if opts.seen_fixed:
        parts.append("--fixed-strings")
    if opts.seen_max:
        parts.append("--max-replacements <LIMIT>")
    if opts.seen_flags:
        parts.append("--flags <FLAGS>")
    if parts:
        return f"Usage: {prog} {' '.join(parts)} <FIND> <REPLACE_WITH> [FILES]..."
    return f"Usage: {prog} <FIND> <REPLACE_WITH> [FILES]..."


def duplicate_error(name: str):
    print_parse_error(f"the argument '{name}' cannot be used multiple times")
    raise ParseExit(2)


def set_bool(opts: Opts, which: str):
    if which == 'preview':
        if opts.seen_preview:
            duplicate_error('--preview')
        opts.preview = True
        opts.seen_preview = True
    elif which == 'fixed':
        if opts.seen_fixed:
            duplicate_error('--fixed-strings')
        opts.fixed = True
        opts.seen_fixed = True


def parse_u64_value(s: str):
    original = s
    if s == "":
        return None, "cannot parse integer from empty string"
    if s.startswith('+'):
        digits = s[1:]
        if digits == "":
            return None, "invalid digit found in string"
    else:
        digits = s
    if digits.startswith('-'):
        return None, "invalid digit found in string"
    if not all('0' <= ch <= '9' for ch in digits):
        return None, "invalid digit found in string"
    try:
        val = int(original, 10)
    except Exception:
        return None, "invalid digit found in string"
    if val < 0:
        return None, "invalid digit found in string"
    if val > 18446744073709551615:
        return None, "number too large to fit in target type"
    return val, None


def set_value(opts: Opts, which: str, value: str):
    if which == 'max':
        if opts.seen_max:
            duplicate_error('--max-replacements <LIMIT>')
        val, err = parse_u64_value(value)
        if err is not None:
            sys.stderr.write(f"error: invalid value '{value}' for '--max-replacements <LIMIT>': {err}\n\nFor more information, try '--help'.\n")
            raise ParseExit(2)
        opts.max_replacements = val
        opts.seen_max = True
    elif which == 'flags':
        if opts.seen_flags:
            duplicate_error('--flags <FLAGS>')
        opts.flags = value
        opts.seen_flags = True


def missing_value_error(opt_display: str):
    sys.stderr.write(f"error: a value is required for '{opt_display}' but none was supplied\n\nFor more information, try '--help'.\n")
    raise ParseExit(2)


def similar_long(arg: str):
    candidates = ['--preview', '--fixed-strings', '--max-replacements', '--flags', '--help', '--version', '--string-mode']
    # Clap suggests for exact prefixes in observed cases.
    matches = [c for c in candidates if c.startswith(arg) and c != arg]
    if len(matches) == 1:
        return matches[0]
    return None


def unexpected_arg(arg: str):
    prog = prog_name()
    sim = similar_long(arg) if arg.startswith('--') else None
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n")
    if sim:
        sys.stderr.write(f"  tip: a similar argument exists: '{sim}'\n\n")
        usage = f"Usage: {prog} <--preview|--fixed-strings|--max-replacements <LIMIT>|--flags <FLAGS>|FIND|REPLACE_WITH|FILES>"
        if sim == '--help':
            usage = f"Usage: {prog} --help <FIND> <REPLACE_WITH> [FILES]..."
        elif sim == '--version':
            usage = f"Usage: {prog} --version <FIND> <REPLACE_WITH> [FILES]..."
        sys.stderr.write(f"{usage}\n\n")
    else:
        sys.stderr.write(f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n")
        sys.stderr.write(f"Usage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\n")
    sys.stderr.write("For more information, try '--help'.\n")
    raise ParseExit(2)


def parse_args(argv):
    opts = Opts()
    end_flags = False
    i = 0
    while i < len(argv):
        arg = argv[i]
        if end_flags:
            opts.positionals.append(arg)
            i += 1
            continue
        if arg == '--':
            end_flags = True
            i += 1
            continue
        if arg == '--help':
            sys.stdout.write(long_help(prog_name()))
            raise ParseExit(0)
        if arg == '--version':
            sys.stdout.write("sd 1.0.0\n")
            raise ParseExit(0)
        if arg.startswith('--') and len(arg) > 2:
            name, eq, val = arg.partition('=')
            if name == '--preview':
                if eq:
                    unexpected_arg(arg)
                set_bool(opts, 'preview')
            elif name in ('--fixed-strings', '--string-mode'):
                if eq:
                    unexpected_arg(arg)
                set_bool(opts, 'fixed')
            elif name == '--max-replacements':
                if eq:
                    value = val
                else:
                    if i + 1 >= len(argv) or argv[i+1].startswith('-'):
                        missing_value_error('--max-replacements <LIMIT>')
                    i += 1
                    value = argv[i]
                set_value(opts, 'max', value)
            elif name == '--flags':
                if eq:
                    value = val
                else:
                    if i + 1 >= len(argv) or argv[i+1].startswith('-'):
                        missing_value_error('--flags <FLAGS>')
                    i += 1
                    value = argv[i]
                set_value(opts, 'flags', value)
            else:
                unexpected_arg(arg)
            i += 1
            continue
        if arg.startswith('-') and arg != '-':
            # short options can be clustered; -f/-n consume the remainder as their value
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch == 'h':
                    sys.stdout.write(short_help(prog_name()))
                    raise ParseExit(0)
                if ch == 'V':
                    sys.stdout.write("sd 1.0.0\n")
                    raise ParseExit(0)
                if ch == 'p':
                    set_bool(opts, 'preview')
                    j += 1
                    continue
                if ch in ('F', 's'):
                    set_bool(opts, 'fixed')
                    j += 1
                    continue
                if ch in ('n', 'f'):
                    rest = arg[j+1:]
                    if rest.startswith('='):
                        rest = rest[1:]
                    if rest == "":
                        if i + 1 >= len(argv) or argv[i+1].startswith('-'):
                            missing_value_error('--max-replacements <LIMIT>' if ch == 'n' else '--flags <FLAGS>')
                        i += 1
                        rest = argv[i]
                    set_value(opts, 'max' if ch == 'n' else 'flags', rest)
                    j = len(arg)
                    continue
                unexpected_arg('-' + ch)
            i += 1
            continue
        opts.positionals.append(arg)
        i += 1

    if len(opts.positionals) < 2:
        missing = []
        if len(opts.positionals) == 0:
            missing = ['<FIND>', '<REPLACE_WITH>']
        elif len(opts.positionals) == 1:
            missing = ['<REPLACE_WITH>']
        sys.stderr.write("error: the following required arguments were not provided:\n")
        for m in missing:
            sys.stderr.write(f"  {m}\n")
        sys.stderr.write(f"\n{active_usage(opts)}\n\nFor more information, try '--help'.\n")
        raise ParseExit(2)
    return opts


def is_ascii_word_char(ch: str) -> bool:
    return ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9') or ch == '_'


def validate_replacement(repl: str):
    i = 0
    n = len(repl)
    while i < n:
        if repl[i] != '$':
            i += 1
            continue
        if i + 1 < n and repl[i+1] == '$':
            i += 2
            continue
        if i + 1 < n and repl[i+1].isdigit():
            j = i + 1
            while j < n and repl[j].isdigit():
                j += 1
            if j < n and (('a' <= repl[j] <= 'z') or ('A' <= repl[j] <= 'Z') or repl[j] == '_'):
                k = j
                while k < n and is_ascii_word_char(repl[k]):
                    k += 1
                digits = repl[i+1:j]
                suffix = repl[j:k]
                sys.stderr.write(f"error: The numbered capture group `${digits}` in the replacement text is ambiguous.\n")
                sys.stderr.write(f"hint: Use curly braces to disambiguate it `${{{digits}}}{suffix}`.\n")
                sys.stderr.write(repl + "\n")
                sys.stderr.write(" " * (i + 1) + "^" * (k - (i + 1)) + "\n")
                return False
            i = j
            continue
        i += 1
    return True


def unescape_replacement(s: str) -> str:
    out = []
    i = 0
    hexdigits = '0123456789abcdefABCDEF'
    while i < len(s):
        ch = s[i]
        if ch != '\\' or i + 1 >= len(s):
            out.append(ch)
            i += 1
            continue
        nxt = s[i+1]
        if nxt == 'n':
            out.append('\n'); i += 2
        elif nxt == 't':
            out.append('\t'); i += 2
        elif nxt == 'r':
            out.append('\r'); i += 2
        elif nxt == '\\':
            out.append('\\'); i += 2
        elif nxt == "'":
            out.append("'"); i += 2
        elif nxt == '"':
            out.append('"'); i += 2
        elif nxt == 'x' and i + 3 < len(s) and s[i+2] in hexdigits and s[i+3] in hexdigits:
            try:
                out.append(chr(int(s[i+2:i+4], 16)))
            except Exception:
                out.append(s[i:i+4])
            i += 4
        elif nxt == 'u' and i + 5 < len(s) and all(c in hexdigits for c in s[i+2:i+6]):
            try:
                out.append(chr(int(s[i+2:i+6], 16)))
            except Exception:
                out.append(s[i:i+6])
            i += 6
        else:
            out.append('\\')
            out.append(nxt)
            i += 2
    return ''.join(out)


def group_value(m, key):
    try:
        if isinstance(key, int):
            val = m.group(key)
        else:
            val = m.group(key)
    except Exception:
        return ''
    return '' if val is None else val


def expand_replacement_template(template: str, m) -> str:
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch != '$':
            out.append(ch)
            i += 1
            continue
        if i + 1 >= n:
            out.append('$')
            i += 1
            continue
        nxt = template[i+1]
        if nxt == '$':
            out.append('$')
            i += 2
            continue
        if nxt == '{':
            end = template.find('}', i+2)
            if end == -1:
                out.append('$')
                i += 1
                continue
            name = template[i+2:end]
            if name.isdigit():
                idx = int(name) if name else 0
                out.append(group_value(m, idx))
            else:
                out.append(group_value(m, name))
            i = end + 1
            continue
        if nxt.isdigit():
            j = i + 1
            while j < n and template[j].isdigit():
                j += 1
            idx_text = template[i+1:j]
            idx = int(idx_text) if idx_text else 0
            out.append(group_value(m, idx))
            i = j
            continue
        if ('a' <= nxt <= 'z') or ('A' <= nxt <= 'Z') or nxt == '_':
            j = i + 1
            while j < n and is_ascii_word_char(template[j]):
                j += 1
            name = template[i+1:j]
            out.append(group_value(m, name))
            i = j
            continue
        out.append('$')
        i += 1
    return unescape_replacement(''.join(out))


def apply_cli_flags(flag_string: str):
    ignorecase = False
    dotall = False
    multiline = True
    word = False
    for ch in flag_string:
        if ch == 'i':
            ignorecase = True
        elif ch == 'c':
            ignorecase = False
        elif ch == 's':
            dotall = True
        elif ch == 'e':
            if not word:
                multiline = False
        elif ch == 'm':
            if not word:
                multiline = True
        elif ch == 'w':
            word = True
            # Observed behavior: w resets case/dot flags that occurred before it and disables multiline.
            ignorecase = False
            dotall = False
            multiline = False
        else:
            # Unknown regex flags are ignored by the original.
            pass
    return ignorecase, dotall, multiline, word


def apply_inline_flag_spec(spec: str, state):
    ignorecase, dotall, multiline, verbose = state
    remove = False
    for ch in spec:
        if ch == '-':
            remove = True
            continue
        if ch == 'i':
            ignorecase = not remove
        elif ch == 's':
            dotall = not remove
        elif ch == 'm':
            multiline = not remove
        elif ch == 'x':
            verbose = not remove
        elif ch == 'U':
            # Rust's ungreedy flag has no direct stdlib equivalent; leave pattern unchanged.
            pass
        else:
            return None
    return ignorecase, dotall, multiline, verbose


def strip_leading_inline_flags(pattern: str, ignorecase: bool, dotall: bool, multiline: bool):
    verbose = False
    while pattern.startswith('(?'):
        close = pattern.find(')')
        if close == -1:
            break
        body = pattern[2:close]
        if body == '' or ':' in body or '<' in body or 'P' in body or '=' in body or '!' in body:
            break
        new_state = apply_inline_flag_spec(body, (ignorecase, dotall, multiline, verbose))
        if new_state is None:
            break
        ignorecase, dotall, multiline, verbose = new_state
        pattern = pattern[close+1:]
    return pattern, ignorecase, dotall, multiline, verbose


def transform_named_groups(pattern: str) -> str:
    # Rust regex accepts (?<name>...), Python wants (?P<name>...). Do not touch look-behind.
    out = []
    i = 0
    while i < len(pattern):
        if pattern.startswith('(?<', i) and i + 3 < len(pattern) and pattern[i+3] not in ('=', '!'):
            out.append('(?P<')
            i += 3
        else:
            out.append(pattern[i])
            i += 1
    return ''.join(out)


def translate_posix_classes(pattern: str) -> str:
    # Python's re does not implement POSIX bracket classes. This covers common ASCII classes.
    mapping = {
        'alnum': 'A-Za-z0-9',
        'alpha': 'A-Za-z',
        'ascii': '\\x00-\\x7F',
        'blank': ' \\t',
        'cntrl': '\\x00-\\x1F\\x7F',
        'digit': '0-9',
        'graph': '\\x21-\\x7E',
        'lower': 'a-z',
        'print': '\\x20-\\x7E',
        'punct': r'''!"\#\$%&'\(\)\*\+,\-\./:;<=>\?@\[\\\]\^_`\{\|\}\~''',
        'space': ' \\t\\r\\n\\v\\f',
        'upper': 'A-Z',
        'word': 'A-Za-z0-9_',
        'xdigit': 'A-Fa-f0-9',
    }
    def repl(m):
        neg = m.group(1) or ''
        name = m.group(2)
        val = mapping.get(name, m.group(0))
        return '[' + ('^' if neg else '') + val + ']'
    return re.sub(r'\[\[:(\^?)([A-Za-z]+):\]\]', repl, pattern)


def has_odd_backslash_before(s: str, pos: int) -> bool:
    cnt = 0
    i = pos - 1
    while i >= 0 and s[i] == '\\':
        cnt += 1
        i -= 1
    return cnt % 2 == 1


def reject_unsupported_regex(pattern: str):
    # Look-around is not supported by Rust regex.
    for token in ['(?=', '(?!', '(?<=', '(?<!']:
        idx = pattern.find(token)
        if idx != -1:
            carets = '^' * len(token)
            sys.stderr.write("error: invalid regex regex parse error:\n")
            sys.stderr.write(f"    {pattern}\n")
            sys.stderr.write("    " + " " * idx + carets + "\n")
            sys.stderr.write("error: look-around, including look-ahead and look-behind, is not supported\n")
            return False
    # Backreferences (including \0) are not supported. Respect escaped backslashes.
    i = 0
    in_class = False
    while i < len(pattern):
        ch = pattern[i]
        if ch == '[' and not has_odd_backslash_before(pattern, i):
            in_class = True
        elif ch == ']' and not has_odd_backslash_before(pattern, i):
            in_class = False
        if ch == '\\' and i + 1 < len(pattern) and pattern[i+1].isdigit():
            # Odd backslash means this is an escape sequence/backreference.
            if not has_odd_backslash_before(pattern, i):
                sys.stderr.write("error: invalid regex regex parse error:\n")
                sys.stderr.write(f"    {pattern}\n")
                sys.stderr.write("    " + " " * i + "^^\n")
                sys.stderr.write("error: backreferences are not supported\n")
                return False
        i += 1
    return True


def compile_regex(find: str, opts: Opts):
    ignorecase, dotall, multiline, word = apply_cli_flags(opts.flags)
    pattern = re.escape(find) if opts.fixed else find
    pattern, ignorecase, dotall, multiline, verbose = strip_leading_inline_flags(pattern, ignorecase, dotall, multiline)
    if word:
        pattern = r'\b(?:' + pattern + r')\b'
    if not opts.fixed:
        if not reject_unsupported_regex(pattern):
            return None
        pattern = transform_named_groups(pattern)
        pattern = translate_posix_classes(pattern)
    flags = 0
    if ignorecase:
        flags |= re.IGNORECASE
    if dotall:
        flags |= re.DOTALL
    if multiline:
        flags |= re.MULTILINE
    if verbose:
        flags |= re.VERBOSE
    try:
        return re.compile(pattern, flags)
    except re.error as e:
        # A Rust-like error envelope. Exact parser diagnostics vary, but this keeps the public shape.
        sys.stderr.write("error: invalid regex regex parse error:\n")
        sys.stderr.write(f"    {find}\n")
        pos = getattr(e, 'pos', None)
        if isinstance(pos, int) and pos >= 0:
            sys.stderr.write("    " + " " * min(pos, len(find)) + "^\n")
        sys.stderr.write(f"error: {e}\n")
        return None


def replace_text(text: str, regex, repl: str, opts: Opts) -> str:
    count = 0 if opts.max_replacements == 0 else opts.max_replacements
    # Python's re count is a Py_ssize_t. Very large u64 values are effectively unlimited for any
    # realistic input in this benchmark.
    if count and count > sys.maxsize:
        count_arg = sys.maxsize
    else:
        count_arg = count
    if opts.fixed:
        def f(_m):
            return repl
    else:
        def f(m):
            return expand_replacement_template(repl, m)
    return regex.sub(f, text, count=count_arg)


def decode_bytes(data: bytes) -> str:
    return data.decode('utf-8', 'surrogateescape')


def encode_text(text: str) -> bytes:
    return text.encode('utf-8', 'surrogateescape')


def os_error_message(exc: OSError) -> str:
    # Rust's Display for io::Error is e.g. "Permission denied (os error 13)".
    if getattr(exc, 'errno', None) is not None:
        return f"{exc.strerror} (os error {exc.errno})"
    return str(exc)


def validate_and_read_files(paths):
    for p in paths:
        if not os.path.exists(p):
            sys.stderr.write(f"error: invalid path: {p}\n")
            return None
    contents = []
    for p in paths:
        try:
            if os.path.isdir(p):
                # The original uses a file mapping path and reports ENODEV for directories on Linux.
                sys.stderr.write("error: No such device (os error 19)\n")
                return None
            with open(p, 'rb') as fh:
                contents.append(fh.read())
        except OSError as e:
            sys.stderr.write(f"error: {os_error_message(e)}\n")
            return None
    return contents


def write_files(paths, data_list):
    for p, data in zip(paths, data_list):
        try:
            with open(p, 'wb') as fh:
                fh.write(data)
        except OSError as e:
            sys.stderr.write(f"error: {os_error_message(e)}\n")
            return False
    return True


def run(opts: Opts) -> int:
    find = opts.positionals[0]
    repl = opts.positionals[1]
    files = opts.positionals[2:]

    if not opts.fixed:
        if not validate_replacement(repl):
            return 1
    regex = compile_regex(find, opts)
    if regex is None:
        return 1

    if files:
        raw_contents = validate_and_read_files(files)
        if raw_contents is None:
            return 1
        replaced_bytes = []
        replaced_texts = []
        for raw in raw_contents:
            text = decode_bytes(raw)
            out = replace_text(text, regex, repl, opts)
            replaced_texts.append(out)
            replaced_bytes.append(encode_text(out))
        if opts.preview:
            if len(files) > 1:
                for p, out in zip(files, replaced_texts):
                    sys.stdout.buffer.write(f"----- FILE {p} -----\n".encode())
                    sys.stdout.buffer.write(encode_text(out))
            else:
                sys.stdout.buffer.write(replaced_bytes[0])
            return 0
        if not write_files(files, replaced_bytes):
            return 1
        return 0
    else:
        try:
            raw = sys.stdin.buffer.read()
        except OSError as e:
            sys.stderr.write(f"error: {os_error_message(e)}\n")
            return 1
        text = decode_bytes(raw)
        out = replace_text(text, regex, repl, opts)
        sys.stdout.buffer.write(encode_text(out))
        return 0


def main():
    try:
        opts = parse_args(sys.argv[1:])
    except ParseExit as e:
        return e.code
    return run(opts)


if __name__ == '__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:
            sys.stderr.close()
        finally:
            sys.exit(0)
